const pool = require('./asyncPool.js');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
(async () => {
  const fail = (m) => { console.error('FAIL', m); process.exit(1); };
  if (JSON.stringify(await pool(2, [], async () => 1)) !== '[]') fail('empty items');
  // Results must be in INPUT order even though later items finish first.
  const out = await pool(2, [30, 20, 10], async (ms) => { await sleep(ms); return ms; });
  if (JSON.stringify(out) !== JSON.stringify([30, 20, 10])) fail('input order, got ' + JSON.stringify(out));
  // Concurrency must never exceed the limit.
  let live = 0, peak = 0;
  await pool(3, Array.from({ length: 12 }, (_, i) => i), async () => {
    live++; peak = Math.max(peak, live); await sleep(5); live--;
  });
  if (peak > 3) fail('peak concurrency ' + peak + ' exceeded limit 3');
  if (peak < 2) fail('did not run concurrently at all, peak ' + peak);
  // A rejection propagates and stops new work.
  let started = 0;
  try {
    await pool(2, Array.from({ length: 20 }, (_, i) => i), async (i) => {
      started++; await sleep(2);
      if (i === 1) throw new Error('boom');
      return i;
    });
    fail('rejection not propagated');
  } catch (e) {
    if (e.message !== 'boom') fail('wrong error: ' + e.message);
  }
  if (started >= 20) fail('kept starting work after a rejection (' + started + ')');
  for (const bad of [0, -1, 1.5, 'x']) {
    let threw = false;
    try { await pool(bad, [1], async (x) => x); } catch (e) { threw = true; }
    if (!threw) fail('bad limit accepted: ' + bad);
  }
  console.log('ok');
})();
